CREATE TABLE aftersale_order (id BIGINT PRIMARY KEY,aftersale_no VARCHAR(64) NOT NULL,order_no VARCHAR(64) NOT NULL,order_item_id BIGINT NOT NULL,user_id BIGINT NOT NULL,merchant_id BIGINT NOT NULL,type VARCHAR(32) NOT NULL,quantity INT NOT NULL,reason VARCHAR(500) NOT NULL,status VARCHAR(32) NOT NULL,requested_amount DECIMAL(18,2) NOT NULL DEFAULT 0,approved_amount DECIMAL(18,2) NOT NULL DEFAULT 0,snapshot_json JSON NOT NULL,created_at TIMESTAMP(3) NOT NULL,updated_at TIMESTAMP(3) NOT NULL,UNIQUE KEY uk_aftersale_no(aftersale_no),KEY idx_after_user(user_id,status),KEY idx_after_merchant(merchant_id,status));
CREATE TABLE aftersale_log (id BIGINT PRIMARY KEY,aftersale_id BIGINT NOT NULL,from_status VARCHAR(32) NULL,to_status VARCHAR(32) NOT NULL,operator_type VARCHAR(32) NOT NULL,operator_id BIGINT NOT NULL,reason VARCHAR(500) NULL,created_at TIMESTAMP(3) NOT NULL);
CREATE TABLE aftersale_evidence (id BIGINT PRIMARY KEY,aftersale_id BIGINT NOT NULL,evidence_type VARCHAR(32) NOT NULL,url VARCHAR(500) NOT NULL,created_at TIMESTAMP(3) NOT NULL);
CREATE TABLE aftersale_arbitration (id BIGINT PRIMARY KEY,aftersale_id BIGINT NOT NULL,reason VARCHAR(500) NOT NULL,status VARCHAR(32) NOT NULL,decision VARCHAR(32) NULL,decision_reason VARCHAR(500) NULL,operator_id BIGINT NULL,created_at TIMESTAMP(3) NOT NULL,decided_at TIMESTAMP(3) NULL,UNIQUE KEY uk_arbitration_aftersale(aftersale_id));
CREATE TABLE product_review (id BIGINT PRIMARY KEY,order_item_id BIGINT NOT NULL,user_id BIGINT NOT NULL,merchant_id BIGINT NOT NULL,score INT NOT NULL,content VARCHAR(1000) NOT NULL,anonymous BOOLEAN NOT NULL,review_status VARCHAR(32) NOT NULL,append_content VARCHAR(1000) NULL,merchant_reply VARCHAR(1000) NULL,created_at TIMESTAMP(3) NOT NULL,updated_at TIMESTAMP(3) NOT NULL,UNIQUE KEY uk_review_item(order_item_id));
